#include "kernel_quartet_optimizer.hpp"
#include <fstream>
#include <iostream>
#include <limits>
int main(int argc,char**argv)try{if(argc!=2)throw std::runtime_error("usage: math-driver INPUT");std::ifstream in(argv[1]);std::string magic;int width,groups;if(!(in>>magic>>width>>groups)||magic!="MMKQUARTETMATH1"||width<1||width>25||groups<0||groups>512)throw std::runtime_error("invalid math header");quartet::Bags bags;for(int i=0;i<groups;++i){int s;uint64_t value;if(!(in>>s>>value)||s<1||s>15||value>=(uint64_t(1)<<width))throw std::runtime_error("invalid math row");bags[s].add(value);}std::string extra;if(in>>extra)throw std::runtime_error("trailing math input");auto bases=quartet::make_bases();auto out=quartet::optimize(bags,bases,std::chrono::steady_clock::now()+std::chrono::seconds(10));if(!out.complete)throw std::runtime_error("math budget exhausted");std::cout<<"{\"score\":"<<out.score<<",\"initial_zeros\":"<<out.zeros<<",\"delta\":"<<out.zeros-out.score<<",\"d\":"<<out.move[0]<<",\"e\":"<<out.move[1]<<",\"f\":"<<out.move[2]<<",\"g\":"<<out.move[3]<<",\"rank\":"<<out.rank<<",\"basis_count\":"<<out.basis_count<<",\"exact_rhs_assignments\":"<<out.workload<<",\"candidate_assignments\":"<<out.candidates<<"}\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}
